import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.PositionTrackingDBClientRequest{RequestAction:
# packet.PositionTrackingDBRequestActionQuery, TrackingID: 7}
QUERY = bytes.fromhex("000e")

# generated by gophertunnel b8bd735:
# packet.PositionTrackingDBClientRequest{RequestAction:
# packet.PositionTrackingDBRequestActionQuery, TrackingID: -300}
NEGATIVE = bytes.fromhex("00d704")

GOLDENS = [
    pytest.param(
        v2225.PositionTrackingDBClientRequestPacket(
            action=v2225.PositionTrackingDBClientRequestPacket.Action.QUERY,
            id=v2225.PositionTrackingId(raw_id=7),
        ),
        QUERY,
        id="query",
    ),
    pytest.param(
        v2225.PositionTrackingDBClientRequestPacket(
            action=v2225.PositionTrackingDBClientRequestPacket.Action.QUERY,
            id=v2225.PositionTrackingId(raw_id=-300),
        ),
        NEGATIVE,
        id="negative-id",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_position_tracking_db_client_request_is_packet_154(version):
    assert version.packets[154] is version.PositionTrackingDBClientRequestPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_position_tracking_db_client_request_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_position_tracking_db_client_request_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
